// Fake "server" for exercise 16. Do not edit this file.
//
// fetchPage(page) pretends to call a server. Pages are numbered from 1 and hold
// 10 items each. After a short delay it resolves with:
//
//   { items: [{ id, title }, ...], hasMore: boolean }
//
// There are 45 items in total, so page 5 has 5 items and says hasMore: false.
// The tests replace this whole module with a mock, so they never wait for the delay.

const PAGE_SIZE = 10
const TOTAL_ITEMS = 45
const DELAY_MS = 500

export function fetchPage(page) {
  return new Promise((resolve) => {
    setTimeout(() => {
      const start = (page - 1) * PAGE_SIZE
      const end = Math.min(start + PAGE_SIZE, TOTAL_ITEMS)
      const items = []
      for (let i = start; i < end; i += 1) {
        items.push({ id: i + 1, title: `Item ${i + 1}` })
      }
      resolve({ items, hasMore: end < TOTAL_ITEMS })
    }, DELAY_MS)
  })
}
